export type EnergyProvider =
  | "openai"
  | "anthropic"
  | "google_genai"
  | "mistralai"
  | "cohere"
  | "huggingface_hub";

export interface EnergyRange {
  min: number;
  max: number;
}

export interface EnergyModelEntry {
  provider: EnergyProvider;
  name: string;
  activeParamsB: EnergyRange;
  totalParamsB: EnergyRange;
  tps: number | null;
  ttft: number | null;
  /** True when the vendor has not disclosed the architecture (estimate). */
  architectureEstimated: boolean;
}

/**
 * How the model name was resolved:
 * - exact:  the name (case-insensitive) is in the EcoLogits catalog
 * - alias:  an EcoLogits alias (e.g. claude-sonnet-4-5 → dated snapshot)
 * - normalized: matched after stripping a vendor prefix or date suffix
 * - family: longest catalog name that prefixes the model id
 * - fallback: unknown model; a wide generic frontier-class range is used
 */
export type EnergyModelMatch = "exact" | "alias" | "normalized" | "family" | "fallback";

export interface InferenceEnergyEstimate {
  energyKwh: EnergyRange & { mid: number };
  matchedModel: string | null;
  match: EnergyModelMatch;
  provider: EnergyProvider | null;
  pue: EnergyRange;
  methodology: string;
}

const GPU_ENERGY_ALPHA = 1.1665273170451914e-6;
const GPU_ENERGY_BETA = -0.011205921025579175;
const GPU_ENERGY_GAMMA = 4.052928146734005e-5;
const LATENCY_ALPHA = 0.0006785088094353663;
const LATENCY_BETA = 0.0003119310311688259;
const LATENCY_GAMMA = 0.019473717579473387;
const GPU_MEMORY_GB = 80;
const SERVER_GPUS = 8;
const SERVER_POWER_KW = 1.2;
const BATCH_SIZE = 64;
const QUANTIZATION_BITS = 16;

export const ENERGY_METHODOLOGY = `ecologits-${ECOLOGITS_VERSION}`;

/** Generic range used when a model is not in the catalog (flagged as fallback). */
const FALLBACK_ENTRY: EnergyModelEntry = {
  provider: "huggingface_hub",
  name: "unknown-model",
  activeParamsB: { min: 44, max: 132 },
  totalParamsB: { min: 440, max: 440 },
  tps: null,
  ttft: null,
  architectureEstimated: true,
};

function toEntry(row: CatalogRow): EnergyModelEntry {
  const [provider, name, aMin, aMax, tMin, tMax, tps, ttft, estimated] = row;
  return {
    provider: PROVIDERS[provider] as EnergyProvider,
    name,
    activeParamsB: { min: aMin, max: aMax },
    totalParamsB: { min: tMin, max: tMax },
    tps,
    ttft,
    architectureEstimated: estimated === 1,
  };
}

export const ENERGY_MODEL_CATALOG: readonly EnergyModelEntry[] = CATALOG.map(toEntry);

const byName = new Map<string, EnergyModelEntry[]>();
function index(key: string, entry: EnergyModelEntry): void {
  const k = key.toLowerCase();
  const list = byName.get(k);
  if (list) {
    if (!list.includes(entry)) list.push(entry);
  } else {
    byName.set(k, [entry]);
  }
}
for (const entry of ENERGY_MODEL_CATALOG) {
  index(entry.name, entry);
  // Open-weight models are catalogued as "org/Model-Name"; hosts usually send the bare name.
  const slash = entry.name.lastIndexOf("/");
  if (slash >= 0) index(entry.name.slice(slash + 1), entry);
}
const aliasMap = new Map<string, string>();
for (const [, alias, target] of ALIASES) {
  aliasMap.set(alias.toLowerCase(), target.toLowerCase());
}
const familyKeys = [...byName.keys()].sort((a, b) => b.length - a.length);

const SDK_TO_ENERGY_PROVIDER: Record<string, EnergyProvider> = {
  openai: "openai",
  anthropic: "anthropic",
  gemini: "google_genai",
  google: "google_genai",
  google_genai: "google_genai",
  mistral: "mistralai",
  mistralai: "mistralai",
  cohere: "cohere",
};

function pick(list: EnergyModelEntry[] | undefined, providerHint?: string): EnergyModelEntry | null {
  if (!list || list.length === 0) return null;
  const hint = providerHint ? SDK_TO_ENERGY_PROVIDER[providerHint.toLowerCase()] : undefined;
  if (hint) {
    const preferred = list.find((e) => e.provider === hint);
    if (preferred) return preferred;
  }
  return list[0] ?? null;
}

function normalizeModelId(raw: string): string {
  let id = raw.trim().toLowerCase();
  // Google: "models/gemini-2.5-pro"; routers: "openai/gpt-5", "anthropic/claude-…"
  id = id.replace(/^models\//, "");
  id = id.replace(/^(openai|anthropic|google|gemini|mistralai|mistral|cohere|vertex_ai|azure|bedrock)\//, "");
  // AWS Bedrock: "us.anthropic.claude-sonnet-4-5-20250929-v1:0"
  id = id.replace(/^(us|eu|apac|global)\./, "");
  id = id.replace(/^(anthropic|meta|mistral|cohere|amazon)\./, "");
  id = id.replace(/-v\d+(:\d+)?$/, "");
  // Vertex: "claude-opus-4-5@20251101"
  id = id.replace(/@\d{8}$/, "");
  return id;
}

function stripDateSuffix(id: string): string {
  return id
    .replace(/-\d{4}-\d{2}-\d{2}$/, "")
    .replace(/-\d{8}$/, "")
    .replace(/-(latest|preview)$/, "");
}

export function resolveEnergyModel(
  modelName: string,
  providerHint?: string
): { entry: EnergyModelEntry; match: EnergyModelMatch } {
  const raw = (modelName || "").trim().toLowerCase();

  const exact = pick(byName.get(raw), providerHint);
  if (exact) return { entry: exact, match: "exact" };

  const aliasTarget = aliasMap.get(raw);
  const aliased = aliasTarget ? pick(byName.get(aliasTarget), providerHint) : null;
  if (aliased) return { entry: aliased, match: "alias" };

  const normalized = normalizeModelId(raw);
  const candidates = [normalized, stripDateSuffix(normalized)];
  for (const candidate of candidates) {
    const direct = pick(byName.get(candidate), providerHint);
    if (direct) return { entry: direct, match: "normalized" };
    const viaAlias = aliasMap.get(candidate);
    const aliasHit = viaAlias ? pick(byName.get(viaAlias), providerHint) : null;
    if (aliasHit) return { entry: aliasHit, match: "normalized" };
  }

  // Longest catalog name that prefixes the id on a "-" boundary, e.g.
  // "gemini-2.5-pro-preview-06-05" → "gemini-2.5-pro".
  for (const key of familyKeys) {
    if (key.length < 4) continue;
    if (normalized.startsWith(`${key}-`)) {
      const entry = pick(byName.get(key), providerHint);
      if (entry) return { entry, match: "family" };
    }
  }

  // Undated short name → its catalogued snapshot, e.g. "claude-3-7-sonnet" →
  // "claude-3-7-sonnet-20250219" (shortest such name wins).
  if (normalized.length >= 4) {
    let best: string | null = null;
    for (const key of familyKeys) {
      if (key.startsWith(`${normalized}-`) && (best === null || key.length < best.length)) {
        best = key;
      }
    }
    const entry = best ? pick(byName.get(best), providerHint) : null;
    if (entry) return { entry, match: "family" };
  }

  return { entry: FALLBACK_ENTRY, match: "fallback" };
}

function pueFor(provider: EnergyProvider | null): EnergyRange {
  const p = provider ? PROVIDER_PUE[provider] : undefined;
  return p ? { min: p[0], max: p[1] } : { min: 1.09, max: 1.2 };
}

function gpuCount(totalParamsB: number): number {
  const memory = (1.2 * totalParamsB * QUANTIZATION_BITS) / 8;
  const gpus = Math.max(1, Math.ceil(memory / GPU_MEMORY_GB));
  return 2 ** Math.ceil(Math.log2(gpus));
}

function requestEnergyKwh(
  activeB: number,
  totalB: number,
  outputTokens: number,
  pue: number,
  tps: number | null,
  ttft: number | null,
  requestLatencySeconds: number
): number {
  const gpuEnergyPerToken =
    (GPU_ENERGY_ALPHA * Math.exp(GPU_ENERGY_BETA * BATCH_SIZE) * activeB + GPU_ENERGY_GAMMA) / 1000;
  const gpuEnergy = outputTokens * gpuEnergyPerToken;

  const latencyPerToken =
    tps && tps > 0 ? 1 / tps : LATENCY_ALPHA * activeB + LATENCY_BETA * BATCH_SIZE + LATENCY_GAMMA;
  const gpuLatency = outputTokens * latencyPerToken + (ttft ?? 0);
  const latency = requestLatencySeconds < gpuLatency ? requestLatencySeconds : gpuLatency;

  const gpus = gpuCount(totalB);
  const serverEnergy = (latency / 3600) * SERVER_POWER_KW * (gpus / SERVER_GPUS) * (1 / BATCH_SIZE);
  return pue * (serverEnergy + gpus * gpuEnergy);
}

/**
 * Estimates inference energy for one request. Never throws; non-finite or
 * negative inputs are treated as zero.
 */
export function estimateInferenceEnergy(params: {
  modelName: string;
  outputTokens: number;
  providerHint?: string;
  /** Measured end-to-end request latency; caps the modelled generation time. */
  requestLatencySeconds?: number;
}): InferenceEnergyEstimate {
  const { entry, match } = resolveEnergyModel(params.modelName, params.providerHint);
  const out = Number.isFinite(params.outputTokens) ? Math.max(0, params.outputTokens) : 0;
  const latency =
    typeof params.requestLatencySeconds === "number" &&
    Number.isFinite(params.requestLatencySeconds) &&
    params.requestLatencySeconds > 0
      ? params.requestLatencySeconds
      : Number.POSITIVE_INFINITY;
  const provider = match === "fallback" ? null : entry.provider;
  const pue = pueFor(provider);

  const low = requestEnergyKwh(
    entry.activeParamsB.min,
    entry.totalParamsB.min,
    out,
    pue.min,
    entry.tps,
    entry.ttft,
    latency
  );
  const high = requestEnergyKwh(
    entry.activeParamsB.max,
    entry.totalParamsB.max,
    out,
    pue.max,
    entry.tps,
    entry.ttft,
    latency
  );
  const min = Math.min(low, high);
  const max = Math.max(low, high);

  return {
    energyKwh: { min, max, mid: (min + max) / 2 },
    matchedModel: match === "fallback" ? null : entry.name,
    match,
    provider,
    pue,
    methodology: ENERGY_METHODOLOGY,
  };
}
